contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 otherKey) public payable {
        require(otherKey != uint256(uint160(address(this))));

        uint256 callerBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 otherBefore = c.balances(address(uint160(otherKey))); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 callerAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 otherAfter = c.balances(address(uint160(otherKey))); if (__ESBMC_reverted()) return;

        assert(otherAfter == otherBefore && (reverted ? callerAfter == callerBefore : callerAfter == 0));
    }

    receive() external payable {}
}

